  merged_data[[var]] <- map_missing(merged_data[[var]])
}

for (var in father_vars) {
  merged_data[[var]] <- map_missing(merged_data[[var]])
}

# Consolidate mother's education
educdtlma <- numeric(length(merged_data$NSID))
for (i in 1:length(merged_data$NSID)) {
