    neg_values <- neg_values[neg_values < 0]
    if (length(neg_values) > 0) {
      educdtlma[i] <- neg_values[1]
    } else {
      educdtlma[i] <- -3
    }
  }
}

# Consolidate father's education
educdtlpa <- numeric(length(merged_data$NSID))
for (i in 1:length(merged_data$NSID)) {
